import time

# In-memory cache for cached results
cache = {}

def cache_result(ttl: int):
    def decorator(func):
        def wrapper(*args, **kwargs):
            # Generate a unique cache key based on the function name, args, and kwargs
            key = f"{func.__name__}:{args}:{kwargs}"

            # Check if the key exists in the cache and is still valid
            if key in cache:
                cache_time, cached_result = cache[key]
                if time.time() - cache_time < ttl:
                    return cached_result

            # If the result is not in cache or expired, compute it
            result = func(*args, **kwargs)
            cache[key] = (time.time(), result)
            return result
        return wrapper
    return decorator

