def levenshtein_distance(s1: str, s2: str) -> int:
    if len(s1) < len(s2):
        return levenshtein_distance(s2, s1)

    # Create a matrix of (len(s1)+1) x (len(s2)+1)
    # Each row i and column j represents the edit distance between s1[:i] and s2[:j]
    matrix = [[0] * (len(s2) + 1) for _ in range(len(s1) + 1)]

    # Initialize the first row and column for base cases
    for i in range(len(matrix)):
        matrix[i][0] = i
    for j in range(len(matrix[0])):
        matrix[0][j] = j

    # Fill the matrix
    for i in range(1, len(matrix)):
        for j in range(1, len(matrix[0])):
            cost = 0 if s1[i - 1] == s2[j - 1] else 1
            matrix[i][j] = min(
                matrix[i - 1][j] + 1,  # Deletion
                matrix[i][j - 1] + 1,  # Insertion
                matrix[i - 1][j - 1] + cost  # Substitution
            )

    return matrix[-1][-1]


def find_closest_match(query: str, names: list[str]) -> str | None:
    if not names:
        return None

    min_distance = float('inf')
    closest_name = None

    for name in names:
        distance = levenshtein_distance(query, name)
        if distance < min_distance:
            min_distance = distance
            closest_name = name

    return closest_name

