import time
from functools import wraps

def cache(ttl):
    def decorator(func):
        cache = {}
        @wraps(func)
        def wrapper(*args, **kwargs):
            key = (args, kwargs)
            if key in cache:
                current_time = time.time()
                if current_time - cache[key][1] < ttl:
                    return cache[key][0]
                else:
                    del cache[key]
            result = func(*args, **kwargs)
            cache[key] = (result, current_time)
            return result
        return wrapper
    return decorator

