def levenshtein_distance(s1, s2):
    if len(s1) < len(s2):
        return levenshtein_distance(s2, s1)
    # s1 is longer or equal in length
    previous_row = range(len(s2) + 1)
    for i, c1 in enumerate(s1, 1):
        current_row = [i] + [0] * len(s2)
        for j, c2 in enumerate(s2, 1):
            if c1 == c2:
                current_row[j] = previous_row[j - 1]
            else:
                current_row[j] = 1 + min(previous_row[j], current_row[j - 1], previous_row[j - 1])
        previous_row = current_row
    return previous_row[-1]

def find_closest_match_manual(query, names):
    best_match = None
    best_ratio = 0
    for name in names:
        dist = levenshtein_distance(query, name)
        max_len = max(len(query), len(name))
        ratio = 1 - (dist / max_len) if max_len > 0 else 0
        if ratio > best_ratio:
            best_ratio = ratio
            best_match = name
    return best_match

def get_env_value(key: str, default: str) -> str:
    """
    Read a value from a .env file, or return the provided default if the key is not found.

    Args:
        key (str): The key to look for in the .env file.
        default (str): The default value to return if the key is not present.

    Returns:
        str: The value for the key from .env, or the default.
    """
    env_vars = {}

    try:
        with open('.env', 'r') as f:
            for line in f:
                line = line.strip()
                if not line or line.startswith('#'):
                    continue
                if '=' in line:
                    k, v = line.split('=', 1)
                    env_vars[k.strip()] = v.strip()
    except FileNotFoundError:
        # If the .env file is not found, return the default
        return default

    return env_vars.get(key, default)

